/**
 * Structural checks on generated bytecode via the disassembler (also what
 * `codetime compile` prints): every byte decodes to a known instruction, and
 * every jump lands on the start of an instruction inside the same function.
 */
import { describe, it, expect } from 'vitest';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { compile, disassembleChunk, disassembleInstruction, OpCode, type Chunk, type FunctionValue } from '../src/index.js';

const examplesDir = path.resolve(__dirname, '../../../examples');

/** Exercises every opcode the compiler emits. */
const EVERY_FEATURE = `
struct Point { x, y }
fn scale(p, k = 2) {
  p.x *= k
  p.y += 1
  return p
}
fn counter() {
  let n = 0
  return fn() {
    n += 1
    return n
  }
}
let tick = counter()
tick()
let p = scale(Point(1, 2))
let items = [1, 2, 3]
items[0] += 10
let obj = { a: 1, b: "two" }
obj["a"] = obj.b
let total = 0
for v in items {
  if v == 2 { continue }
  if v > 100 { break }
  total += v
}
let i = 0
while not (i >= 3) {
  i = i + 1
}
print(-total, 2 ** 3, 7 % 4, 9 / 3, i != 3, i < 1 or i <= 0, true and false, null, items.length, "s"[0])
let fns = []
for k in [1, 2] {
  let captured = k - 1
  fns.push(fn() { return captured })
}
print(fns[0](), fns[1]())
`;

/** The script chunk and every nested function's chunk. */
function allChunks(chunk: Chunk, name = 'main'): { name: string; chunk: Chunk }[] {
  const result = [{ name, chunk }];
  for (const c of chunk.constants) {
    if (c !== null && typeof c === 'object' && c.kind === 'function') {
      result.push(...allChunks((c as FunctionValue).chunk, (c as FunctionValue).name));
    }
  }
  return result;
}

function checkChunk(chunk: Chunk): { ops: Set<OpCode> } {
  const starts = new Set<number>();
  const ops = new Set<OpCode>();
  const targets: number[] = [];
  let offset = 0;
  while (offset < chunk.code.length) {
    starts.add(offset);
    ops.add(chunk.code[offset] as OpCode);
    const { output, nextOffset } = disassembleInstruction(chunk, offset);
    expect(output).not.toContain('UNKNOWN_OP');
    expect(nextOffset).toBeGreaterThan(offset);
    const jump = /-> (\d+)/.exec(output);
    if (jump) targets.push(Number(jump[1]));
    offset = nextOffset;
  }
  expect(offset).toBe(chunk.code.length);
  for (const target of targets) {
    expect(starts.has(target) || target === chunk.code.length).toBe(true);
  }
  expect(chunk.locations.length).toBe(chunk.code.length);
  return { ops };
}

describe('Bytecode disassembly', () => {
  const sources: [string, string][] = [
    ['every-feature', EVERY_FEATURE],
    ...fs.readdirSync(examplesDir).filter(f => f.endsWith('.ct'))
      .map(f => [f, fs.readFileSync(path.join(examplesDir, f), 'utf-8')] as [string, string]),
  ];

  it.each(sources)('%s: every byte decodes and every jump lands on an instruction', (_name, src) => {
    const result = compile(src);
    expect(result.diagnostics).toEqual([]);
    for (const { chunk } of allChunks(result.chunk!)) checkChunk(chunk);
  });

  it('the feature program uses every opcode except OP_HALT', () => {
    const result = compile(EVERY_FEATURE);
    const used = new Set<OpCode>();
    for (const { chunk } of allChunks(result.chunk!)) for (const op of checkChunk(chunk).ops) used.add(op);
    const all = Object.values(OpCode).filter((v): v is OpCode => typeof v === 'number');
    const missing = all.filter(op => !used.has(op) && op !== OpCode.OP_HALT).map(op => OpCode[op]);
    expect(missing).toEqual([]);
  });

  it('prints a readable listing with names, constants and jump targets', () => {
    const listing = disassembleChunk(compile('let x = 1\nif x > 0 { print("yes") }').chunk!, 'main');
    expect(listing.split('\n')[0]).toBe('== main ==');
    expect(listing).toMatch(/OP_CONSTANT\s+\d+ \('1'\)/);
    expect(listing).toMatch(/OP_DEFINE_GLOBAL/);
    expect(listing).toMatch(/OP_JUMP_IF_FALSE\s+-> \d{4}/);
    expect(listing).toMatch(/OP_PRINT/);
  });

  it('feature program output is the same on the VM and the replay debugger', async () => {
    const { VM, TimeTravelDebugger } = await import('../src/index.js');
    const res = new VM(EVERY_FEATURE).interpret(EVERY_FEATURE);
    expect(res.error).toBeUndefined();
    expect(res.output).toEqual(['-14 8 3 3 false false false null 3 s', '0 1']);
    expect(TimeTravelDebugger.fromSource(EVERY_FEATURE).gotoEnd().snapshot.output).toEqual(res.output);
  });
});
